import{_ as t,o as e,c as i,a2 as d}from"./chunks/framework.D8Tso2Ul.js";const u=JSON.parse('{"title":"Módulo: Incidentes","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/incidentes.md","filePath":"modulos/incidentes.md"}'),n={name:"modulos/incidentes.md"};function s(o,a,c,r,l,p){return e(),i("div",null,[...a[0]||(a[0]=[d(`<h1 id="modulo-incidentes" tabindex="-1">Módulo: Incidentes <a class="header-anchor" href="#modulo-incidentes" aria-label="Permalink to &quot;Módulo: Incidentes&quot;">​</a></h1><p><strong>Ubicación:</strong> <code>Frontend/src/pages/Incidents.tsx</code> · <code>Backend/handlers/incidents-module/</code></p><p>Sistema completo para la gestión de eventos de seguridad laboral: hallazgos, incidentes, accidentes y condiciones subestándar, con reporte, seguimiento y análisis estadístico.</p><h2 id="tipos-y-clasificacion" tabindex="-1">Tipos y clasificación <a class="header-anchor" href="#tipos-y-clasificacion" aria-label="Permalink to &quot;Tipos y clasificación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Clasificación</th><th>Tipo</th><th>Descripción</th></tr></thead><tbody><tr><td>Hallazgo</td><td>Acción</td><td>Acto subestándar observado (conducta insegura)</td></tr><tr><td>Hallazgo</td><td>Condición</td><td>Condición subestándar del entorno</td></tr><tr><td>Incidente</td><td>—</td><td>Evento que pudo causar daño (cuasi-accidente)</td></tr><tr><td>Accidente</td><td>—</td><td>Evento con lesión o daño efectivo</td></tr></tbody></table><p><strong>Niveles de gravedad:</strong> <code>leve</code>, <code>grave</code>, <code>fatal</code>.</p><h2 id="reporte-de-incidentes" tabindex="-1">Reporte de incidentes <a class="header-anchor" href="#reporte-de-incidentes" aria-label="Permalink to &quot;Reporte de incidentes&quot;">​</a></h2><p>El formulario captura:</p><ul><li><strong>Clasificación y tipo</strong> (hallazgo/incidente/accidente).</li><li><strong>Trabajador afectado</strong>: nombre, RUT, cargo, género.</li><li><strong>Etapa constructiva</strong> en que ocurrió el evento.</li><li><strong>Fecha, hora y centro de trabajo</strong>.</li><li><strong>Gravedad</strong> y <strong>días perdidos</strong>.</li><li><strong>Evidencias fotográficas</strong> (múltiples archivos a S3).</li><li><strong>Confirmación de veracidad</strong> del reporte.</li></ul><h2 id="flujo-de-notificacion-automatica" tabindex="-1">Flujo de notificación automática <a class="header-anchor" href="#flujo-de-notificacion-automatica" aria-label="Permalink to &quot;Flujo de notificación automática&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Una persona reporta un incidente (POST /incidents)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. Se guarda en IncidentsTable con autoría y timestamp</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. EventBus emite &quot;incident.created&quot;</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. Notificación automática al prevencionista vía InboxTable</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>5. (Opcional) Publicación en tópico SNS para integraciones externas</span></span></code></pre></div><h2 id="visualizacion-y-analisis" tabindex="-1">Visualización y análisis <a class="header-anchor" href="#visualizacion-y-analisis" aria-label="Permalink to &quot;Visualización y análisis&quot;">​</a></h2><h3 id="vista-listado" tabindex="-1">Vista listado <a class="header-anchor" href="#vista-listado" aria-label="Permalink to &quot;Vista listado&quot;">​</a></h3><p>Tabla con filtros avanzados por tipo, estado y rango de fechas.</p><h3 id="vista-estadisticas-dashboard-analitico" tabindex="-1">Vista estadísticas (dashboard analítico) <a class="header-anchor" href="#vista-estadisticas-dashboard-analitico" aria-label="Permalink to &quot;Vista estadísticas (dashboard analítico)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>KPI</th><th>Qué mide</th></tr></thead><tbody><tr><td>Tasa de accidentabilidad</td><td>Accidentes por cada 100 trabajadores</td></tr><tr><td>Días perdidos</td><td>Total de días de ausencia por accidentes</td></tr><tr><td>Siniestralidad</td><td>Severidad acumulada en el período</td></tr></tbody></table><p>Incluye además:</p><ul><li>Gráfico de <strong>evolución temporal</strong> (líneas).</li><li>Distribución por <strong>clasificación</strong> (barras horizontales).</li><li>Distribución por <strong>gravedad</strong> (barras horizontales).</li><li><strong>Calendario heatmap</strong> mensual con severidad por día.</li><li>Exportación de reportes en <strong>CSV y PDF</strong>.</li></ul><h2 id="detalle-de-un-incidente" tabindex="-1">Detalle de un incidente <a class="header-anchor" href="#detalle-de-un-incidente" aria-label="Permalink to &quot;Detalle de un incidente&quot;">​</a></h2><p>Modal con información completa: galería de evidencias con lightbox, datos del trabajador y del reportante, estado y seguimiento del evento.</p><h2 id="estados" tabindex="-1">Estados <a class="header-anchor" href="#estados" aria-label="Permalink to &quot;Estados&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reportado → en_investigacion → cerrado</span></span></code></pre></div><p>El ciclo de investigación se alinea con la exigencia del DS 44 de <strong>investigar incidentes con análisis de causa raíz</strong>.</p><h2 id="endpoints-relacionados" tabindex="-1">Endpoints relacionados <a class="header-anchor" href="#endpoints-relacionados" aria-label="Permalink to &quot;Endpoints relacionados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Ruta</th><th>Acción</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/incidents</code></td><td>Crear incidente</td></tr><tr><td><code>GET</code></td><td><code>/incidents</code></td><td>Listar con filtros</td></tr><tr><td><code>GET</code></td><td><code>/incidents/{id}</code></td><td>Detalle</td></tr><tr><td><code>PUT</code></td><td><code>/incidents/{id}</code></td><td>Actualizar</td></tr><tr><td><code>GET</code></td><td><code>/incidents/stats</code></td><td>Estadísticas</td></tr><tr><td><code>GET</code></td><td><code>/incidents/analytics</code></td><td>Datos del dashboard</td></tr><tr><td><code>POST</code></td><td><code>/incidents/quick-report</code></td><td>Reporte rápido vía QR</td></tr></tbody></table><p>Ver detalle en <a href="/manual/api/incidentes.html">API · Incidentes</a>.</p>`,26)])])}const b=t(n,[["render",s]]);export{u as __pageData,b as default};
